--
-- TOC entry 269 (class 1259 OID 33081)
-- Name: vw_referencia_geracao; Type: VIEW; Schema: dw_campo_real; Owner: -
--

CREATE VIEW dw_campo_real.vw_referencia_geracao AS
 SELECT g.id_usina_dw,
    t.mes,
    t.hora,
    count(*) AS quantidade_amostras,
    round(avg(g.geracao_mwh), 4) AS geracao_media_mwh
   FROM (dw_campo_real.fato_geracao g
     JOIN dw_campo_real.dim_tempo t ON ((t.id_tempo = g.id_tempo)))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM dw_campo_real.fato_parada_hora p
          WHERE ((p.id_usina_dw = g.id_usina_dw) AND (p.id_tempo = g.id_tempo)))))
  GROUP BY g.id_usina_dw, t.mes, t.hora;


--
-- TOC entry 270 (class 1259 OID 33086)
-- Name: vw_estimativa_paradas; Type: VIEW; Schema: dw_campo_real; Owner: -
--

CREATE VIEW dw_campo_real.vw_estimativa_paradas AS
 SELECT p.id_parada_origem,
    p.id_usina_dw,
    u.cod_usina,
    u.nome AS nome_usina,
    p.id_tempo,
    t.data_hora,
    t.mes,
    t.hora,
    p.tipo_parada,
    p.motivo,
    p.horas_indisponiveis,
    r.quantidade_amostras,
    r.geracao_media_mwh,
        CASE
            WHEN (r.quantidade_amostras >= 5) THEN round((r.geracao_media_mwh * p.horas_indisponiveis), 3)
            ELSE NULL::numeric
        END AS energia_potencial_mwh,
        CASE
            WHEN (r.quantidade_amostras >= 5) THEN 'ESTIMADO'::text
            ELSE 'SEM_REFERENCIA_SUFICIENTE'::text
        END AS status_estimativa
   FROM (((dw_campo_real.fato_parada_hora p
     JOIN dw_campo_real.dim_tempo t ON ((t.id_tempo = p.id_tempo)))
     JOIN dw_campo_real.dim_usina u ON ((u.id_usina_dw = p.id_usina_dw)))
     LEFT JOIN dw_campo_real.vw_referencia_geracao r ON (((r.id_usina_dw = p.id_usina_dw) AND (r.mes = t.mes) AND (r.hora = t.hora))));


--
-- TOC entry 271 (class 1259 OID 33091)
-- Name: vw_estimativa_paradas_v2; Type: VIEW; Schema: dw_campo_real; Owner: -
--

CREATE VIEW dw_campo_real.vw_estimativa_paradas_v2 AS
 WITH amostras_validas AS (
         SELECT g.id_usina_dw,
            t.ano,
            t.mes,
            t.hora,
            g.geracao_mwh
           FROM (dw_campo_real.fato_geracao g
             JOIN dw_campo_real.dim_tempo t ON ((t.id_tempo = g.id_tempo)))
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM dw_campo_real.fato_parada_hora p
                  WHERE ((p.id_usina_dw = g.id_usina_dw) AND (p.id_tempo = g.id_tempo)))))
        ), referencia_mensal AS (
         SELECT amostras_validas.id_usina_dw,
            amostras_validas.ano,
            amostras_validas.mes,
            amostras_validas.hora,
            count(*) AS quantidade_amostras,
            round(avg(amostras_validas.geracao_mwh), 4) AS geracao_media_mwh
           FROM amostras_validas
          GROUP BY amostras_validas.id_usina_dw, amostras_validas.ano, amostras_validas.mes, amostras_validas.hora
        ), referencia_anual AS (
         SELECT amostras_validas.id_usina_dw,
            amostras_validas.ano,
            amostras_validas.hora,
            count(*) AS quantidade_amostras,
            round(avg(amostras_validas.geracao_mwh), 4) AS geracao_media_mwh
           FROM amostras_validas
          GROUP BY amostras_validas.id_usina_dw, amostras_validas.ano, amostras_validas.hora
        ), estimativas AS (
         SELECT p.id_parada_origem,
            p.id_usina_dw,
            u.cod_usina,
            u.nome AS nome_usina,
            p.id_tempo,
            t.data_hora,
            t.ano,
            t.mes,
            t.hora,
            p.tipo_parada,
            p.motivo,
            p.horas_indisponiveis,
                CASE
                    WHEN (rm.quantidade_amostras >= 5) THEN rm.quantidade_amostras
                    WHEN (ra.quantidade_amostras >= 5) THEN ra.quantidade_amostras
                    ELSE (0)::bigint
                END AS quantidade_amostras,
                CASE
                    WHEN (rm.quantidade_amostras >= 5) THEN rm.geracao_media_mwh
                    WHEN (ra.quantidade_amostras >= 5) THEN ra.geracao_media_mwh
                    ELSE NULL::numeric
                END AS geracao_referencia_mwh,
                CASE
                    WHEN (rm.quantidade_amostras >= 5) THEN 'MENSAL'::text
                    WHEN (ra.quantidade_amostras >= 5) THEN 'ANUAL'::text
                    ELSE 'SEM_REFERENCIA'::text
                END AS metodo_referencia
           FROM ((((dw_campo_real.fato_parada_hora p
             JOIN dw_campo_real.dim_tempo t ON ((t.id_tempo = p.id_tempo)))
             JOIN dw_campo_real.dim_usina u ON ((u.id_usina_dw = p.id_usina_dw)))
             LEFT JOIN referencia_mensal rm ON (((rm.id_usina_dw = p.id_usina_dw) AND (rm.ano = t.ano) AND (rm.mes = t.mes) AND (rm.hora = t.hora))))
             LEFT JOIN referencia_anual ra ON (((ra.id_usina_dw = p.id_usina_dw) AND (ra.ano = t.ano) AND (ra.hora = t.hora))))
        )
 SELECT id_parada_origem,
    id_usina_dw,
    cod_usina,
    nome_usina,
    id_tempo,
    data_hora,
    ano,
    mes,
    hora,
    tipo_parada,
    motivo,
    horas_indisponiveis,
    quantidade_amostras,
    geracao_referencia_mwh,
    metodo_referencia,
    round((geracao_referencia_mwh * horas_indisponiveis), 3) AS energia_potencial_mwh,
        CASE
            WHEN (metodo_referencia = 'SEM_REFERENCIA'::text) THEN 'SEM_REFERENCIA_SUFICIENTE'::text
            ELSE 'ESTIMADO'::text
        END AS status_estimativa
   FROM estimativas;


--
-- TOC entry 272 (class 1259 OID 40960)
-- Name: vw_usinas_fonte_scd; Type: VIEW; Schema: dw_campo_real; Owner: -
--

CREATE VIEW dw_campo_real.vw_usinas_fonte_scd AS
 SELECT u.id_usina AS id_usina_origem,
    btrim((u.cod_usina)::text) AS cod_usina,
    btrim((u.nome)::text) AS nome,
    df.id_fonte_dw,
    ds.id_submercado_dw,
    (
        CASE
            WHEN (btrim((u.cod_usina)::text) = 'CRE-BIO-005'::text) THEN 'SP'::text
            ELSE btrim((u.uf)::text)
        END)::character(2) AS uf,
    NULLIF(btrim((u.municipio)::text), ''::text) AS municipio,
        CASE
            WHEN (btrim((u.cod_usina)::text) = 'CRE-UFV-004'::text) THEN (- abs(u.latitude))
            ELSE u.latitude
        END AS latitude,
    u.longitude,
    u.potencia_mw,
        CASE
            WHEN (btrim((u.cod_usina)::text) = 'CRE-UFV-006'::text) THEN '2019-02-01'::date
            ELSE u.data_inicio_operacao
        END AS data_inicio_operacao,
    btrim((u.situacao)::text) AS situacao,
        CASE
            WHEN (btrim((u.cod_usina)::text) = 'CRE-BIO-005'::text) THEN 'UF corrigida PE para SP conforme SQL original'::text
            WHEN (btrim((u.cod_usina)::text) = 'CRE-UFV-004'::text) THEN 'Latitude corrigida conforme SQL original'::text
            WHEN (btrim((u.cod_usina)::text) = 'CRE-UFV-006'::text) THEN 'Data de operacao corrigida conforme SQL original'::text
            ELSE 'Cadastro original sem correcao'::text
        END AS observacao_tratamento
   FROM ((((campo_real_energia.usina u
     JOIN campo_real_energia.fonte_energia fo ON ((fo.id_fonte = u.id_fonte)))
     JOIN dw_campo_real.dim_fonte df ON (((btrim((df.cod_fonte)::text) = btrim((fo.cod_fonte)::text)) AND (df.id_fonte_dw <> 0))))
     JOIN campo_real_energia.submercado sm ON ((btrim((sm.cod_submercado)::text) = btrim((u.cod_submercado)::text))))
     JOIN dw_campo_real.dim_submercado ds ON (((btrim((ds.cod_submercado)::text) = btrim((sm.cod_submercado)::text)) AND (ds.id_submercado_dw <> 0))))
  WHERE (btrim((u.cod_usina)::text) <> 'CRE-EOL-07'::text);


