--
-- TOC entry 244 (class 1259 OID 24763)
-- Name: medicao_classificada; Type: VIEW; Schema: tratado_campo_real; Owner: -
--

CREATE VIEW tratado_campo_real.medicao_classificada AS
 WITH classificacao AS (
         SELECT m.id_medicao,
            m.id_usina,
            m.data_hora,
            m.energia_mwh,
            m.disponibilidade_mw,
            m.origem,
            m.recebido_em,
            count(*) OVER (PARTITION BY m.id_usina, m.data_hora) AS quantidade_duplicatas,
            row_number() OVER (PARTITION BY m.id_usina, m.data_hora ORDER BY
                CASE
                    WHEN ((m.origem)::text = 'SCADA'::text) THEN 0
                    ELSE 1
                END, m.recebido_em, m.id_medicao) AS prioridade
           FROM campo_real_energia.medicao_geracao m
        )
 SELECT id_medicao,
    id_usina,
    data_hora,
    energia_mwh,
    disponibilidade_mw,
    origem,
    recebido_em,
    quantidade_duplicatas,
    prioridade,
        CASE
            WHEN (prioridade = 1) THEN 'MANTER_PROVISORIAMENTE'::text
            WHEN ((origem)::text = 'MANUAL'::text) THEN 'QUARENTENA_REVISAO_MANUAL'::text
            ELSE 'QUARENTENA_REPROCESSAMENTO'::text
        END AS decisao
   FROM classificacao;


--
-- TOC entry 245 (class 1259 OID 32768)
-- Name: medicao_avaliada; Type: VIEW; Schema: tratado_campo_real; Owner: -
--

CREATE VIEW tratado_campo_real.medicao_avaliada AS
 SELECT m.id_medicao,
    m.id_usina,
    m.data_hora,
    m.energia_mwh,
    m.disponibilidade_mw,
    m.origem,
    m.recebido_em,
    u.cod_usina,
    u.potencia_mw,
        CASE
            WHEN (m.prioridade > 1) THEN m.decisao
            WHEN ((m.id_usina IS NULL) OR (u.id_usina IS NULL)) THEN 'QUARENTENA_USINA_INVALIDA'::text
            WHEN ((m.data_hora IS NULL) OR (m.data_hora < '2025-01-01 00:00:00'::timestamp without time zone) OR (m.data_hora >= '2026-01-01 00:00:00'::timestamp without time zone)) THEN 'QUARENTENA_DATA_INVALIDA'::text
            WHEN (m.energia_mwh IS NULL) THEN 'QUARENTENA_ENERGIA_NULA'::text
            WHEN (m.energia_mwh < (0)::numeric) THEN 'QUARENTENA_ENERGIA_NEGATIVA'::text
            WHEN (m.energia_mwh > u.potencia_mw) THEN 'QUARENTENA_ACIMA_POTENCIA'::text
            WHEN (((f.cod_fonte)::text = 'UFV'::text) AND (m.energia_mwh > (0)::numeric) AND ((EXTRACT(hour FROM m.data_hora) < (6)::numeric) OR (EXTRACT(hour FROM m.data_hora) >= (19)::numeric))) THEN 'QUARENTENA_SOLAR_NOTURNA'::text
            WHEN ((m.energia_mwh > (0)::numeric) AND (EXISTS ( SELECT 1
               FROM campo_real_energia.parada_usina p
              WHERE ((p.id_usina = m.id_usina) AND (p.fim >= p.inicio) AND ((m.data_hora >= p.inicio) AND (m.data_hora <= p.fim)))))) THEN 'QUARENTENA_GERACAO_EM_PARADA'::text
            ELSE 'APTO_PROVISORIO'::text
        END AS situacao_qualidade
   FROM ((tratado_campo_real.medicao_classificada m
     LEFT JOIN campo_real_energia.usina u ON ((u.id_usina = m.id_usina)))
     LEFT JOIN campo_real_energia.fonte_energia f ON ((f.id_fonte = u.id_fonte)));


--
-- TOC entry 246 (class 1259 OID 32773)
-- Name: medicao_avaliada_v2; Type: VIEW; Schema: tratado_campo_real; Owner: -
--

CREATE VIEW tratado_campo_real.medicao_avaliada_v2 AS
 WITH base AS (
         SELECT medicao_classificada.id_medicao,
            medicao_classificada.id_usina,
            medicao_classificada.data_hora,
            medicao_classificada.energia_mwh,
            lag(medicao_classificada.energia_mwh) OVER (PARTITION BY medicao_classificada.id_usina ORDER BY medicao_classificada.data_hora) AS energia_anterior,
            lag(medicao_classificada.data_hora) OVER (PARTITION BY medicao_classificada.id_usina ORDER BY medicao_classificada.data_hora) AS hora_anterior
           FROM tratado_campo_real.medicao_classificada
          WHERE ((medicao_classificada.prioridade = 1) AND (medicao_classificada.data_hora >= '2025-01-01 00:00:00'::timestamp without time zone) AND (medicao_classificada.data_hora < '2026-01-01 00:00:00'::timestamp without time zone))
        ), grupos AS (
         SELECT base.id_medicao,
            base.id_usina,
            base.data_hora,
            base.energia_mwh,
            base.energia_anterior,
            base.hora_anterior,
            sum(
                CASE
                    WHEN ((base.energia_mwh > (0)::numeric) AND (base.energia_mwh = base.energia_anterior) AND (base.data_hora = (base.hora_anterior + '01:00:00'::interval))) THEN 0
                    ELSE 1
                END) OVER (PARTITION BY base.id_usina ORDER BY base.data_hora) AS grupo
           FROM base
        ), travamentos AS (
         SELECT grupos.id_usina,
            grupos.grupo
           FROM grupos
          WHERE (grupos.energia_mwh > (0)::numeric)
          GROUP BY grupos.id_usina, grupos.grupo
         HAVING (count(*) >= 12)
        ), medicoes_travadas AS (
         SELECT g.id_medicao
           FROM (grupos g
             JOIN travamentos t_1 ON (((t_1.id_usina = g.id_usina) AND (t_1.grupo = g.grupo))))
        )
 SELECT a.id_medicao,
    a.id_usina,
    a.data_hora,
    a.energia_mwh,
    a.disponibilidade_mw,
    a.origem,
    a.recebido_em,
    a.cod_usina,
    a.potencia_mw,
    a.situacao_qualidade,
        CASE
            WHEN (t.id_medicao IS NOT NULL) THEN true
            ELSE false
        END AS medidor_travado,
        CASE
            WHEN ((a.situacao_qualidade = 'APTO_PROVISORIO'::text) AND (t.id_medicao IS NOT NULL)) THEN 'QUARENTENA_MEDIDOR_TRAVADO'::text
            ELSE a.situacao_qualidade
        END AS situacao_final,
        CASE
            WHEN (a.recebido_em IS NULL) THEN 'SEM_RECEBIMENTO'::text
            WHEN (a.recebido_em < a.data_hora) THEN 'RECEBIMENTO_ANTECIPADO'::text
            WHEN (a.recebido_em > (a.data_hora + '24:00:00'::interval)) THEN 'RECEBIMENTO_ATRASADO'::text
            ELSE 'DENTRO_DO_PRAZO'::text
        END AS alerta_atualidade
   FROM (tratado_campo_real.medicao_avaliada a
     LEFT JOIN medicoes_travadas t ON ((t.id_medicao = a.id_medicao)));


